/// Error enum for Rbin
public struct RbinErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        /// The specified retention rule lock request can't be completed.
        case conflictException(Rbin.ConflictException)
        /// The service could not respond to the request due to an internal problem.
        case internalServerException
        /// The specified resource was not found.
        case resourceNotFoundException(Rbin.ResourceNotFoundException)
        /// The request would cause a service quota for the number of tags per resource to be exceeded.
        case serviceQuotaExceededException(Rbin.ServiceQuotaExceededException)
        /// One or more of the parameters in the request is not valid.
        case validationException(Rbin.ValidationException)
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "ConflictException":
            let context = try singleValueContainer.decode(Rbin.ConflictException.self)
            self.error = .conflictException(context)
        case "InternalServerException": self.error = .internalServerException
        case "ResourceNotFoundException":
            let context = try singleValueContainer.decode(Rbin.ResourceNotFoundException.self)
            self.error = .resourceNotFoundException(context)
        case "ServiceQuotaExceededException":
            let context = try singleValueContainer.decode(Rbin.ServiceQuotaExceededException.self)
            self.error = .serviceQuotaExceededException(context)
        case "ValidationException":
            let context = try singleValueContainer.decode(Rbin.ValidationException.self)
            self.error = .validationException(context)
        default:
            throw responseError
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .conflictException: "ConflictException"
        case .internalServerException: "InternalServerException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .serviceQuotaExceededException: "ServiceQuotaExceededException"
        case .validationException: "ValidationException"
        }
    }
}
